{
  "items": [
    {
      "name": "MvPolynomial.aeval_natDegree_le",
      "module_name": "Mathlib.RingTheory.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {σ : Type v} {R : Type u_2} [inst : CommSemiring R] {m n : ℕ} (F : MvPolynomial σ R),\n  F.totalDegree ≤ m →\n    ∀ (f : σ → Polynomial R), (∀ (i : σ), (f i).natDegree ≤ n) → ((MvPolynomial.aeval f) F).natDegree ≤ m * n"
    },
    {
      "name": "MvPolynomial.IsHomogeneous.aeval",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Homogeneous",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_3} {S : Type u_4} [inst : CommSemiring R] [inst_1 : CommSemiring S]\n  {φ : MvPolynomial σ R} {m n : ℕ} [inst_2 : Algebra R S],\n  φ.IsHomogeneous m →\n    ∀ (g : σ → MvPolynomial τ S), (∀ (i : σ), (g i).IsHomogeneous n) → ((MvPolynomial.aeval g) φ).IsHomogeneous (n * m)"
    },
    {
      "name": "Polynomial.aeval",
      "module_name": "Mathlib.Algebra.Polynomial.AlgebraMap",
      "kind": "definition",
      "type": "{R : Type u} →\n  {A : Type z} → [inst : CommSemiring R] → [inst_1 : Semiring A] → [inst_2 : Algebra R A] → A → Polynomial R →ₐ[R] A"
    },
    {
      "name": "MvPolynomial.IsHomogeneous.eval₂",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Homogeneous",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_3} {S : Type u_4} [inst : CommSemiring R] [inst_1 : CommSemiring S]\n  {φ : MvPolynomial σ R} {m n : ℕ},\n  φ.IsHomogeneous m →\n    ∀ (f : R →+* MvPolynomial τ S) (g : σ → MvPolynomial τ S),\n      (∀ (r : R), (f r).IsHomogeneous 0) →\n        (∀ (i : σ), (g i).IsHomogeneous n) → (MvPolynomial.eval₂ f g φ).IsHomogeneous (n * m)"
    },
    {
      "name": "Polynomial.degree_map_le",
      "module_name": "Mathlib.Algebra.Polynomial.Eval.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : Semiring R] [inst_1 : Semiring S] {f : R →+* S} {p : Polynomial R},\n  (Polynomial.map f p).degree ≤ p.degree"
    }
  ]
}
